import { useState } from "react"
import type * as React from "react"
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type PaginationState,
  type RowSelectionState,
  type SortingState,
  type Table as TanstackTable,
  type TableOptions,
  type VisibilityState,
} from "@tanstack/react-table"

import { cn } from "@/registry/mbank/lib/utils"
import { DataTableBody } from "./data-table-body"
import { DataTableToolbar } from "./data-table-toolbar"
import { Pagination } from "./pagination"
import { Table, TableHead, TableHeader, TableRow } from "./table"

/*
 * CRM `TableSection 2.0` as a shadcn data table on @tanstack/react-table: sorting
 * (DataTableColumnHeader), global search and column visibility (DataTableToolbar), row selection
 * (dataTableSelectColumn), Skeleton rows while loading, an empty slot and the kit Pagination.
 * Server-side data: pass tableOptions { manualPagination, rowCount, state, on*Change }.
 */
type DataTableProps<TData, TValue> = {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  /** Shows Skeleton rows instead of data (first load). */
  loading?: boolean
  loadingRows?: number
  /** Rendered in one full-width cell when there are no rows, e.g. <EmptyState />. */
  empty?: React.ReactNode
  /** Toolbar above the table; default = search + column menu. Pass null to hide it. */
  toolbar?: ((table: TanstackTable<TData>) => React.ReactNode) | null
  searchPlaceholder?: string
  /** false hides the pagination row (short lists). */
  paginated?: boolean
  pageSizeOptions?: number[]
  initialPageSize?: number
  /** Stable id for row selection, e.g. (row) => row.id. */
  getRowId?: (row: TData, index: number) => string
  /** Escape hatch for every other TanStack option (controlled state, manual pagination ...). */
  tableOptions?: Partial<TableOptions<TData>>
  className?: string
  "aria-label"?: string
}

function DataTable<TData, TValue>({
  columns,
  data,
  loading = false,
  loadingRows = 5,
  empty,
  toolbar,
  searchPlaceholder,
  paginated = true,
  pageSizeOptions,
  initialPageSize = 20,
  getRowId,
  tableOptions,
  className,
  "aria-label": ariaLabel,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = useState<SortingState>([])
  const [globalFilter, setGlobalFilter] = useState("")
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({})
  const [pagination, setPagination] = useState<PaginationState>({ pageIndex: 0, pageSize: initialPageSize })

  const table = useReactTable({
    data,
    columns,
    getRowId,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: paginated ? getPaginationRowModel() : undefined,
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    onPaginationChange: setPagination,
    ...tableOptions,
    state: { sorting, globalFilter, columnVisibility, rowSelection, pagination, ...tableOptions?.state },
  })

  const { pageIndex, pageSize } = table.getState().pagination
  const rowCount = table.getRowCount()
  const from = rowCount === 0 ? 0 : pageIndex * pageSize + 1
  const to = Math.min((pageIndex + 1) * pageSize, rowCount)

  return (
    <div data-slot="data-table" className={cn("flex flex-col gap-4", className)}>
      {toolbar === undefined ? <DataTableToolbar table={table} searchPlaceholder={searchPlaceholder} /> : toolbar?.(table)}
      <div className="overflow-hidden rounded-lg border border-border bg-card">
        <Table aria-label={ariaLabel} aria-busy={loading || undefined}>
          <TableHeader>
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id} className="hover:bg-transparent">
                {group.headers.map((header) => {
                  const sorted = header.column.getIsSorted()
                  return (
                    <TableHead
                      key={header.id}
                      colSpan={header.colSpan}
                      aria-sort={sorted === "asc" ? "ascending" : sorted === "desc" ? "descending" : undefined}
                    >
                      {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <DataTableBody table={table} loading={loading} loadingRows={loadingRows} empty={empty} />
        </Table>
      </div>
      {paginated && (
        <Pagination
          page={pageIndex + 1}
          pageCount={table.getPageCount()}
          onPageChange={(page) => table.setPageIndex(page - 1)}
          pageSize={pageSize}
          pageSizeOptions={pageSizeOptions}
          onPageSizeChange={(size) => table.setPageSize(size)}
          summary={rowCount > 0 ? `${from}–${to} из ${rowCount}` : undefined}
        />
      )}
    </div>
  )
}

export { DataTable }
export type { DataTableProps }

import type * as React from "react"
import { flexRender, type Table as TanstackTable } from "@tanstack/react-table"

import { Skeleton } from "./skeleton"
import { TableBody, TableCell, TableRow } from "./table"

type DataTableBodyProps<TData> = {
  table: TanstackTable<TData>
  loading: boolean
  loadingRows: number
  empty?: React.ReactNode
}

/** Rows of DataTable: Skeleton rows while loading, one full-width empty cell, or the page rows. */
function DataTableBody<TData>({ table, loading, loadingRows, empty }: DataTableBodyProps<TData>) {
  const columns = table.getVisibleLeafColumns()
  const rows = table.getRowModel().rows

  if (loading) {
    return (
      <TableBody data-slot="data-table-body">
        {Array.from({ length: loadingRows }, (_, i) => (
          <TableRow key={i} className="hover:bg-transparent">
            {columns.map((column) => (
              <TableCell key={column.id}>
                <Skeleton className="h-4 w-full max-w-40" />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    )
  }

  if (rows.length === 0) {
    return (
      <TableBody data-slot="data-table-body">
        <TableRow className="hover:bg-transparent">
          <TableCell colSpan={columns.length} className="h-32 text-center whitespace-normal text-muted-foreground">
            {empty ?? "Нет данных"}
          </TableCell>
        </TableRow>
      </TableBody>
    )
  }

  return (
    <TableBody data-slot="data-table-body">
      {rows.map((row) => (
        <TableRow key={row.id} data-state={row.getIsSelected() ? "selected" : undefined}>
          {row.getVisibleCells().map((cell) => (
            <TableCell key={cell.id}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</TableCell>
          ))}
        </TableRow>
      ))}
    </TableBody>
  )
}

export { DataTableBody }

import type * as React from "react"
import type { Column, Table as TanstackTable } from "@tanstack/react-table"

import { cn } from "@/registry/mbank/lib/utils"
import { Button } from "./button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "./dropdown-menu"
import { ColumnsIcon, SearchIcon } from "./icons"
import { Input } from "./input"

type DataTableToolbarProps<TData> = React.ComponentProps<"div"> & {
  table: TanstackTable<TData>
  searchPlaceholder?: string
  /** false hides the search input (filters live elsewhere). */
  searchable?: boolean
  /** false hides the column visibility menu. */
  columnsMenu?: boolean
  columnsLabel?: string
}

/** Column title for the visibility menu: string header, else meta.label, else the column id. */
function columnLabel<TData>(column: Column<TData, unknown>) {
  const { header, meta } = column.columnDef
  if (typeof header === "string") return header
  const label = (meta as { label?: unknown } | undefined)?.label
  return typeof label === "string" ? label : column.id
}

/**
 * Above DataTable: global search (Figma `input/search`, size S), extra filters / actions as
 * children, and the column visibility menu. Works with any TanStack table instance.
 */
function DataTableToolbar<TData>({
  table,
  searchPlaceholder = "Поиск",
  searchable = true,
  columnsMenu = true,
  columnsLabel = "Колонки",
  className,
  children,
  ...props
}: DataTableToolbarProps<TData>) {
  const hideable = table.getAllLeafColumns().filter((column) => column.getCanHide())

  return (
    <div data-slot="data-table-toolbar" className={cn("flex flex-wrap items-center gap-2", className)} {...props}>
      {searchable && (
        <div className="relative w-full max-w-xs">
          <SearchIcon className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            size="sm"
            value={String(table.getState().globalFilter ?? "")}
            onChange={(event) => table.setGlobalFilter(event.target.value)}
            placeholder={searchPlaceholder}
            aria-label={searchPlaceholder}
            className="pl-9"
          />
        </div>
      )}
      {children}
      {columnsMenu && hideable.length > 0 && (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm" className="ml-auto">
              <ColumnsIcon />
              {columnsLabel}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuLabel>{columnsLabel}</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {hideable.map((column) => (
              <DropdownMenuCheckboxItem
                key={column.id}
                checked={column.getIsVisible()}
                onCheckedChange={(value) => column.toggleVisibility(Boolean(value))}
                onSelect={(event) => event.preventDefault()}
              >
                {columnLabel(column)}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  )
}

export { DataTableToolbar }
export type { DataTableToolbarProps }

import type * as React from "react"
import type { Column, ColumnDef } from "@tanstack/react-table"

import { cn } from "@/registry/mbank/lib/utils"
import { Checkbox } from "./checkbox"
import { ArrowDownIcon, ArrowUpIcon, ChevronsUpDownIcon } from "./icons"

type DataTableColumnHeaderProps<TData, TValue> = React.ComponentProps<"div"> & {
  column: Column<TData, TValue>
  title: string
}

/**
 * CRM `item/table-cell/header/sorter`: Sort order inactive / ↑ ascending / ↓ descending.
 * Click cycles asc -> desc -> off (TanStack starts number columns with desc); aria-sort is on the <th>.
 */
function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
  ...props
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) return <div className={className} {...props}>{title}</div>

  const sorted = column.getIsSorted()
  const Icon = sorted === "asc" ? ArrowUpIcon : sorted === "desc" ? ArrowDownIcon : ChevronsUpDownIcon
  return (
    <div data-slot="data-table-column-header" className={cn("flex items-center", className)} {...props}>
      <button
        type="button"
        onClick={column.getToggleSortingHandler()}
        className="-mx-1.5 inline-flex h-8 items-center gap-1 rounded-sm px-1.5 font-medium transition-colors outline-none hover:bg-accent hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/30 data-[sorted=true]:text-foreground"
        data-sorted={Boolean(sorted)}
      >
        {title}
        <Icon className="size-4 shrink-0" aria-hidden="true" />
      </button>
    </div>
  )
}

/** Leading checkbox column: select the page in the header, a row in each cell. */
function dataTableSelectColumn<TData>(labels: { all?: string; row?: string } = {}): ColumnDef<TData> {
  return {
    id: "select",
    enableSorting: false,
    enableHiding: false,
    header: ({ table }) => (
      <Checkbox
        checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")}
        onCheckedChange={(value) => table.toggleAllPageRowsSelected(Boolean(value))}
        aria-label={labels.all ?? "Выбрать все строки"}
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        disabled={!row.getCanSelect()}
        onCheckedChange={(value) => row.toggleSelected(Boolean(value))}
        aria-label={labels.row ?? "Выбрать строку"}
      />
    ),
  }
}

export { DataTableColumnHeader, dataTableSelectColumn }
export type { DataTableColumnHeaderProps }
